13	
14	/// <summary>
15	/// Class for accessing the list of collections in a Azure AI Search vector store.
16	/// </summary>
17	/// <remarks>
18	/// This class can be used with collections of any schema type, but requires you to provide schema information when getting a collection.
19	/// </remarks>
20	public sealed class AzureAISearchVectorStore : IVectorStore
21	{
22	    /// <summary>The name of this database for telemetry purposes.</summary>
23	    private const string DatabaseName = "AzureAISearch";
24	
25	    /// <summary>Azure AI Search client that can be used to manage the list of indices in an Azure AI Search Service.</summary>
26	    private readonly SearchIndexClient _searchIndexClient;
27	
28	    /// <summary>Optional configuration options for this class.</summary>
29	    private readonly AzureAISearchVectorStoreOptions _options;
30	
31	    /// <summary>
32	    /// Initializes a new instance of the <see cref="AzureAISearchVectorStore"/> class.
33	    /// </summary>
34	    /// <param name="searchIndexClient">Azure AI Search client that can be used to manage the list of indices in an Azure AI Search Service.</param>
35	    /// <param name="options">Optional configuration options for this class.</param>
36	    public AzureAISearchVectorStore(SearchIndexClient searchIndexClient, AzureAISearchVectorStoreOptions? options = default)
37	    {
38	        Verify.NotNull(searchIndexClient);
39	
40	        this._searchIndexClient = searchIndexClient;
41	        this._options = options ?? new AzureAISearchVectorStoreOptions();
42	    }
43	
44	    /// <inheritdoc />
45	    public IVectorStoreRecordCollection<TKey, TRecord> GetCollection<TKey, TRecord>(string name, VectorStoreRecordDefinition? vectorStoreRecordDefinition = null) where TRecord : class
46	    {
47	        if (typeof(TKey) != typeof(string))
48	        {
49	            throw new NotSupportedException("Only string keys are supported.");
50	        }
51	
52	        if (this._options.VectorStoreCollectionFactory is not null)
53	        {
54	            return this._options.VectorStoreCollectionFactory.CreateVectorStoreRecordCollection<TKey, TRecord>(this._searchIndexClient, name, vectorStoreRecordDefinition);
55	        }
56	
57	        var directlyCreatedStore = new AzureAISearchVectorStoreRecordCollection<TRecord>(this._searchIndexClient, name, new AzureAISearchVectorStoreRecordCollectionOptions<TRecord>() { VectorStoreRecordDefinition = vectorStoreRecordDefinition }) as IVectorStoreRecordCollection<TKey, TRecord>;
58	        return directlyCreatedStore!;
59	    }
60	
61	    /// <inheritdoc />
62	    public async IAsyncEnumerable<string> ListCollectionNamesAsync([EnumeratorCancellation] CancellationToken cancellationToken = default)
63	    {
64	        var indexNamesEnumerable = this._searchIndexClient.GetIndexNamesAsync(cancellationToken).ConfigureAwait(false);
65	        var indexNamesEnumerator = indexNamesEnumerable.GetAsyncEnumerator();
66	
67	        var nextResult = await GetNextIndexNameAsync(indexNamesEnumerator).ConfigureAwait(false);
68	        while (nextResult.more)
69	        {
70	            yield return nextResult.name;
71	            nextResult = await GetNextIndexNameAsync(indexNamesEnumerator).ConfigureAwait(false);
72	        }
73	    }
74	
75	    /// <summary>
76	    /// Helper method to get the next index name from the enumerator with a try catch around the move next call to convert
77	    /// any <see cref="RequestFailedException"/> to <see cref="HttpOperationException"/>, since try catch is not supported
78	    /// around a yield return.
79	    /// </summary>
80	    /// <param name="enumerator">The enumerator to get the next result from.</param>
81	    /// <returns>A value indicating whether there are more results and the current string if true.</returns>
82	    private static async Task<(string name, bool more)> GetNextIndexNameAsync(ConfiguredCancelableAsyncEnumerable<string>.Enumerator enumerator)
83	    {
84	        const string OperationName = "GetIndexNames";
85	
86	        try
87	        {
88	            var more = await enumerator.MoveNextAsync();
89	            return (enumerator.Current, more);
90	        }
91	        catch (AggregateException ex) when (ex.InnerException is RequestFailedException innerEx)
92	        {
93	            throw new VectorStoreOperationException("Call to vector store failed.", ex)
94	            {
95	                VectorStoreType = DatabaseName,
96	                OperationName = OperationName
97	            };
98	        }
99	        catch (RequestFailedException ex)
100	        {
101	            throw new VectorStoreOperationException("Call to vector store failed.", ex)
102	            {
103	                VectorStoreType = DatabaseName,
104	                OperationName = OperationName
105	            };
106	        }
107	    }
108	}
